using Amazon.S3;
using Amazon.S3.Model;
using Amazon.S3.Util;

var s3Client = new AmazonS3Client("accessKey", "secretKey", RegionEndpoint.USEast1);

string bucketName = "my-dotnet-bucket";
string key = "documents/report.pdf";

// Create bucket if it does not exist
if (!await AmazonS3Util.DoesS3BucketExistAsync(s3Client, bucketName))
{
    await s3Client.PutBucketAsync(new PutBucketRequest { BucketName = bucketName, UseClientRegion = true });
}

// Upload a file
PutObjectRequest request = new PutObjectRequest
{
    BucketName = bucketName,
    Key = key,
    FilePath = "./report.pdf"
};
await s3Client.PutObjectAsync(request);
Console.WriteLine($"Uploaded: s3://{bucketName}/{key}");

// List objects
ListObjectsRequest list = new ListObjectsRequest { BucketName = bucketName };
ListObjectsResponse response = await s3Client.ListObjectsAsync(list);
foreach (S3Object obj in response.S3Objects)
{
    Console.WriteLine(obj.Key);
}

GetPreSignedUrlRequest urlRequest = new GetPreSignedUrlRequest
{
    BucketName = bucketName,
    Key = key,
    Expires = DateTime.UtcNow.AddHours(1),
    Verb = HttpVerb.GET
};

string url = s3Client.GetPreSignedURL(urlRequest);
Console.WriteLine(url);
